def find_Divisor(start, end):
    max_divisor = 1
    for i in range(start, end + 1):
        for j in range(2, int(math.sqrt(i)) + 1):
            if i % j == 0:
                max_divisor = max(max_divisor, i // j)
    return max_divisor
