def counting_sort(arr):
  n = len(arr)
  max_val = max(arr)
  count = [0] * (max_val + 1)
  for i in range(n):
    count[arr[i]] += 1
  sorted_arr = [0] * n
  for i in range(max_val + 1):
    count[i] += 1
    for j in range(i + 1, max_val + 1):
      count[j] = count[j] + count[j - 1]
  for i in range(n - 1, -1, -1):
    sorted_arr[count[arr[i]] - 1] = arr[i]
    count[arr[i]] -= 1
  return sorted_arr

